-- Representative schema from wownow aftersale; no application data.

CREATE TABLE tickets (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ticket_sn VARCHAR(32) NOT NULL UNIQUE,
    consumer_id BIGINT NOT NULL,
    distributor_id BIGINT NOT NULL,
    order_sn VARCHAR(32) NOT NULL,
    previous_order_state VARCHAR(32) NOT NULL DEFAULT '',
    status SMALLINT NOT NULL DEFAULT 1,
    reason TEXT NOT NULL DEFAULT '',
    description TEXT,
    image_urls TEXT[],
    phone VARCHAR(32) NOT NULL DEFAULT '',
    email VARCHAR(128) NOT NULL DEFAULT '',
    ticket_type VARCHAR(16) NOT NULL DEFAULT 'refund',
    initiator_type VARCHAR(16) NOT NULL DEFAULT '',
    initiator_id BIGINT,
    issue_type VARCHAR(32) NOT NULL DEFAULT '',
    issue_source VARCHAR(16) NOT NULL DEFAULT '',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    closed_at TIMESTAMPTZ,
    UNIQUE(consumer_id, order_sn)
);

CREATE TABLE ticket_messages (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ticket_id BIGINT NOT NULL REFERENCES tickets(id),
    sender_type VARCHAR(16) NOT NULL DEFAULT '',
    sender_id BIGINT NOT NULL,
    content TEXT NOT NULL DEFAULT '',
    image_urls TEXT[],
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE typed_arrays (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    flags BOOLEAN[],
    counters BIGINT[],
    weights DOUBLE PRECISION[]
);
